static void setup(Combat*g){combat_init(g,1500,1500,NULL,NULL);g->jobId=2;g->joblevel=50;g->skillPoints=49;g->level=20;g->statPoints=stat_budget(20);stat_refresh(g);dev_restore(g);g->ranks[17]=4;g->ranks[26]=10;g->skillPoints=35;g->debugFreeze=1;for(int i=0;i<MOB_COUNT;i++)g->mobs[i].enabled=g->mobs[i].hp=0;}
static void target(Combat*g,int i,float x){CombatMob*m=&g->mobs[i];memset(m,0,sizeof(*m));m->enabled=m->training=1;m->kind=1;m->hp=m->testMaxHP=10000;m->x=m->homeX=x;m->y=m->homeY=1500;m->spawnDef=-1;}
static void tick(Combat*g,int n){for(int i=0;i<n;i++)combat_tick(g,.05f,0,0);}
static int totals(Combat*g,int value){int n=0;for(unsigned i=0;i<g->damageNext&&i<DAMAGE_EVENTS;i++){DamageEvent*d=&g->damage[i];if(d->kind==1&&d->value==value)n++;}return n;}
