 setup(&g);target(&g,0,1540);g.debugImmortal=0;g.mobs[0].hp=200;assert(skill_cast(&g,30,1540,1500));tick(&g,10);assert(!g.mobs[0].hp&&totals(&g,230)==1);tick(&g,80);assert(totals(&g,230)==1);
